fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Initialize max value and index at start of prefix
    let mut max_val = v[0];
    let mut max_idx = 0;
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Initialize min value and index at start of suffix
    let mut min_val = v[start];
    let mut min_idx = start;
    for i in start+1..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // If p is the last index, condition is vacuously true
    if p + 1 == v.len() {
        return true;
    }

    // Find max in prefix [0..=p]
    let (max_val, _) = find_max_in_prefix(v, p);

    // Find min in suffix [p+1..end]
    let (min_val, _) = find_min_in_suffix(v, p+1);

    // Check strict partition barrier condition
    max_val < min_val
}